//! Byte-for-byte interop vectors generated by the iShareScreen Python
//! reference (its SRTP/SRTCP encryptors, record cipher and message
//! builders) from fixed inputs. They pin our wire format to an
//! implementation known to work against real hosts.

use std::io::Cursor;

use crate::proto::clipboard;
use crate::proto::messages::{self, DisplayRequest};
use crate::proto::record::{Opened, RecordKeys, RecordOpener, RecordSealer};
use crate::rtp::rtcp;
use crate::rtp::srtp::{SrtcpReceiver, SrtcpSender, SrtpReceiver, SrtpSender};

const SRTP0: &str = "806500000000000011223344e61ff78171622103f46bf9f375ef";
const SRTP1: &str = "80650001000001e0112233442472631bdd1dc1bd4d9cf1d365d5";
const KEYFRAME: &str = "80c90001aabbccdd84ce0004aabbccdd00000000010203040700000081ce0002aabbccdd0102030480c0000101020304";
const KEYFRAME_SRTCP0: &str = "80c90001aabbccddf102c7a6d44d18b02b9e3ac6e4b100a82a0168497c4928ae84bfc52534aae5a266442f1eb3e99331800000006d09dc31795b00fa968e";
const NACK: &str = "80c90001aabbccdd81cd0005aabbccdd010203040064000500750000008c0000";
const LTR: &str = "80cc0003aabbccdd0000000500001234";
const LTR_SRTCP1: &str = "80cc0003aabbccdd73321f1bfe80620d80000001fac37922258b4f79bafb";
const BLOB1103: &str = "00000001f39ebcb1c9015b786c0d98dccd780bd82903f3e55692697a3b10bbaeaab20ac1";
const REC0: &str = "0020b9240a240eb5b5e0533f37f46b64c974776d981fda19bff1e3e47a46836f8a17";
const REC1: &str = "0040a4a57000855917519acce2d6c5af24776e85c012b42cffa32c4b73e3c6285fe202c9d74dd4309368957046c26e34e31a698f6d0db2b49bd8c9a3f8123f470d6d";
const VD: &str = "";
const KEY: &str = "040100000000ffe3";
const PTR: &str = "10005a8e07a1cd34c75988f2edfd55ccc3b4";
const CLIP: &str = "1f000000000000000000003600000036789c62606060646060102b284dcac94cd62b2d49b3d02dc849ccccd32d49ad286140009e8cc32b7372f2b9caf38b725200000000ffff";
const AUTO: &str = "1500000100000000";
const REQ: &str = "0b00000000000000";

fn hex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn blob(f: impl Fn(usize) -> u8) -> [u8; 46] {
    std::array::from_fn(f)
}

const OURS: u32 = 0xAABBCCDD;
const MEDIA: u32 = 0x01020304;

#[test]
fn srtp_matches_reference() {
    let key = blob(|i| i as u8);
    let mut tx = SrtpSender::new(&key, 0x11223344);
    assert_eq!(tx.protect(101, &[0x00, 0x68, 0x34, 0x00]), hex(SRTP0));
    assert_eq!(tx.protect(101, &[0x00, 0x68, 0x34, 0x00]), hex(SRTP1));
    let mut rx = SrtpReceiver::new(&key);
    let p = rx.unprotect(&hex(SRTP1)).expect("reference SRTP packet decrypts");
    assert_eq!((p.ssrc, p.seq, p.pt), (0x11223344, 1, 101));
    assert_eq!(p.payload, [0x00, 0x68, 0x34, 0x00]);
}

#[test]
fn rtcp_matches_reference() {
    assert_eq!(rtcp::recovery_request(rtcp::Recovery::FirPli, OURS, MEDIA, 7), hex(KEYFRAME));
    assert_eq!(rtcp::nack(OURS, MEDIA, &[100, 101, 103, 117, 140]).unwrap(), hex(NACK));
    assert_eq!(rtcp::ltr_ack(OURS, 0x1234), hex(LTR));
}

#[test]
fn srtcp_matches_reference() {
    let key = blob(|i| (i * 7 + 3) as u8);
    let mut tx = SrtcpSender::new(&key);
    assert_eq!(tx.protect(&hex(KEYFRAME)), hex(KEYFRAME_SRTCP0));
    assert_eq!(tx.protect(&hex(LTR)), hex(LTR_SRTCP1));
    let rx = SrtcpReceiver::new(&key);
    assert_eq!(rx.unprotect(&hex(LTR_SRTCP1)).unwrap(), hex(LTR));
}

#[test]
fn record_layer_matches_reference() {
    let auth: [u8; 16] = std::array::from_fn(|i| 16 + i as u8);
    let keys = RecordKeys::unwrap(&hex(BLOB1103), &auth).unwrap();
    assert_eq!(keys.key, std::array::from_fn::<u8, 16, _>(|i| 100 + i as u8));
    let mut sealer = RecordSealer::new(&keys);
    assert_eq!(sealer.seal(&hex("0400000100000061")), hex(REC0));
    assert_eq!(sealer.seal(&[b'x'; 40]), hex(REC1));

    let mut opener = RecordOpener::new(&keys);
    let mut wire = Cursor::new([hex(REC0), hex(REC1)].concat());
    assert!(matches!(opener.read(&mut wire).unwrap(), Opened::Message(m) if m == hex("0400000100000061")));
    assert!(matches!(opener.read(&mut wire).unwrap(), Opened::Message(m) if m == [b'x'; 40]));
}

#[test]
fn messages_match_reference() {
    let req = DisplayRequest { width: 1600, height: 900, scale: 2.0 };
    assert_eq!(messages::set_display_configuration(&req), hex(VD));
    assert_eq!(messages::key_event(true, 0xffe3), hex(KEY));
    let k: [u8; 16] = std::array::from_fn(|i| 100 + i as u8);
    assert_eq!(messages::encrypted_pointer_event(&k, 1, 1234, 567), hex(PTR));
    // Deflate output differs between zlib implementations; compare the
    // header and the inflated item list instead of raw bytes.
    let (ours, theirs) = (clipboard::send_text("héllo\nworld"), hex(CLIP));
    assert_eq!(ours[..12], theirs[..12]);
    let inflate = |m: &[u8]| {
        let mut out = Vec::new();
        let _ = std::io::Read::read_to_end(&mut flate2::read::ZlibDecoder::new(&m[16..]), &mut out);
        out
    };
    assert_eq!(inflate(&ours), inflate(&theirs));
    assert_eq!(clipboard::text_from_message(&theirs).as_deref(), Some("héllo\nworld"));
    assert_eq!(clipboard::enable_auto_pasteboard(), hex(AUTO));
    assert_eq!(clipboard::request_pasteboard(), hex(REQ));
}
